import React, { useCallback, useEffect, useState } from 'react';
import {
  Alert,
  Box,
  Button,
  Card,
  CardContent,
  Chip,
  CircularProgress,
  FormControl,
  InputLabel,
  LinearProgress,
  MenuItem,
  Select,
  Stack,
  Step,
  StepLabel,
  Stepper,
  TextField,
  Typography,
} from '@mui/material';
import ApiService from '../../services/api';

type VerifierWorkflow = {
  framework: string;
  label: string;
  standard: string;
  workflow?: {
    workflowReadinessScore?: number;
    steps?: Array<{ id: string; label: string; status: string; description?: string }>;
  };
  request?: {
    id?: string;
    status?: string;
    verifierName?: string;
    verifierEmail?: string;
  } | null;
};

type VerifierBundle = {
  workflows?: VerifierWorkflow[];
  summary?: {
    workflowReadinessScore?: number;
    pendingStatements?: number;
  };
  disclaimer?: string;
};

const FRAMEWORK_OPTIONS = [
  { value: 'iso14064', label: 'ISO 14064-3' },
  { value: 'iso14067', label: 'ISO 14067' },
  { value: 'brsr', label: 'BRSR P6.4' },
  { value: 'cbam', label: 'CBAM' },
];

type ThirdPartyVerifierPanelProps = {
  period?: string;
  /** When true, hides standalone orchestration CTA — parent hub runs full readiness check. */
  embedded?: boolean;
};

const ThirdPartyVerifierPanel: React.FC<ThirdPartyVerifierPanelProps> = ({
  period = 'annual',
  embedded = false,
}) => {
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [bundle, setBundle] = useState<VerifierBundle | null>(null);
  const [requestFramework, setRequestFramework] = useState('iso14064');
  const [verifierName, setVerifierName] = useState('');
  const [verifierEmail, setVerifierEmail] = useState('');
  const [submitting, setSubmitting] = useState(false);
  const [feedback, setFeedback] = useState<string | null>(null);

  const loadWorkflow = useCallback(async () => {
    setLoading(true);
    setError(null);
    try {
      const res = await ApiService.getThirdPartyVerifierWorkflow({ period });
      setBundle((res?.data as VerifierBundle) || null);
    } catch (e) {
      setError(e instanceof Error ? e.message : 'Unable to load verifier workflow');
    } finally {
      setLoading(false);
    }
  }, [period]);

  useEffect(() => {
    void loadWorkflow();
  }, [loadWorkflow]);

  const submitVerifierRequest = async () => {
    if (!verifierName.trim() || !verifierEmail.trim()) {
      setFeedback('Verifier name and email are required.');
      return;
    }
    setSubmitting(true);
    setFeedback(null);
    try {
      await ApiService.createThirdPartyVerifierRequest({
        framework: requestFramework,
        verifierName: verifierName.trim(),
        verifierEmail: verifierEmail.trim(),
        assuranceLevel: 'limited',
      });
      setFeedback('Verifier request recorded. Share your audit pack export with the accredited body.');
      setVerifierName('');
      setVerifierEmail('');
      await loadWorkflow();
    } catch (e) {
      setFeedback(e instanceof Error ? e.message : 'Could not create verifier request');
    } finally {
      setSubmitting(false);
    }
  };

  if (loading) {
    return (
      <Box sx={{ display: 'flex', justifyContent: 'center', py: 4 }}>
        <CircularProgress size={28} />
      </Box>
    );
  }

  if (error) {
    return <Alert severity="error">{error}</Alert>;
  }

  const workflows = bundle?.workflows || [];
  const readinessScore = bundle?.summary?.workflowReadinessScore ?? 0;

  return (
    <Stack spacing={2}>
      {bundle?.disclaimer ? <Alert severity="info">{bundle.disclaimer}</Alert> : null}
      {embedded ? (
        <Alert severity="info">
          Verifier evidence is prepared when you run <strong>Check my reporting readiness</strong> at the top of this track.
        </Alert>
      ) : null}
      {feedback ? <Alert severity="info">{feedback}</Alert> : null}

      <Card variant="outlined">
        <CardContent>
          <Typography variant="subtitle2" color="text.secondary" gutterBottom>
            Verifier handoff readiness
          </Typography>
          <Stack direction="row" alignItems="center" spacing={2}>
            <Typography variant="h5">{readinessScore}%</Typography>
            <Box sx={{ flex: 1 }}>
              <LinearProgress
                variant="determinate"
                value={Math.min(100, readinessScore)}
                sx={{ height: 8, borderRadius: 1 }}
              />
            </Box>
            {(bundle?.summary?.pendingStatements || 0) > 0 ? (
              <Chip size="small" color="warning" label={`${bundle?.summary?.pendingStatements} pending`} />
            ) : null}
          </Stack>
        </CardContent>
      </Card>

      {workflows.map((workflow) => (
        <Card key={workflow.framework} variant="outlined">
          <CardContent>
            <Stack direction="row" justifyContent="space-between" alignItems="center" sx={{ mb: 2 }}>
              <Box>
                <Typography variant="subtitle1">{workflow.label}</Typography>
                <Typography variant="caption" color="text.secondary">{workflow.standard}</Typography>
              </Box>
              <Chip
                size="small"
                label={`${workflow.workflow?.workflowReadinessScore ?? 0}%`}
                color="primary"
                variant="outlined"
              />
            </Stack>
            <Stepper
              activeStep={workflow.workflow?.steps?.filter((s) => s.status === 'complete').length || 0}
              alternativeLabel
              sx={{ display: { xs: 'none', sm: 'flex' } }}
            >
              {(workflow.workflow?.steps || []).map((step) => (
                <Step key={step.id} completed={step.status === 'complete'}>
                  <StepLabel error={step.status === 'gap'}>{step.label}</StepLabel>
                </Step>
              ))}
            </Stepper>
            <Stack spacing={0.5} sx={{ display: { xs: 'flex', sm: 'none' } }}>
              {(workflow.workflow?.steps || []).map((step) => (
                <Typography key={step.id} variant="body2" color="text.secondary">
                  {step.status === 'complete' ? '✓' : '○'} {step.label}
                </Typography>
              ))}
            </Stack>
            {workflow.request ? (
              <Alert severity="success" sx={{ mt: 2 }}>
                Verifier requested: {workflow.request.verifierName} ({workflow.request.status})
              </Alert>
            ) : null}
          </CardContent>
        </Card>
      ))}

      <Card variant="outlined">
        <CardContent>
          <Typography variant="subtitle1" gutterBottom>Record your accredited verifier</Typography>
          <Typography variant="body2" color="text.secondary" sx={{ mb: 2 }}>
            After your readiness check, share the audit pack export with your verifier and record their details here.
          </Typography>
          <Stack spacing={2} direction={{ xs: 'column', sm: 'row' }} flexWrap="wrap">
            <FormControl size="small" sx={{ minWidth: 180 }}>
              <InputLabel>Framework</InputLabel>
              <Select
                value={requestFramework}
                label="Framework"
                onChange={(e) => setRequestFramework(e.target.value)}
              >
                {FRAMEWORK_OPTIONS.map((option) => (
                  <MenuItem key={option.value} value={option.value}>{option.label}</MenuItem>
                ))}
              </Select>
            </FormControl>
            <TextField
              size="small"
              label="Verifier name"
              value={verifierName}
              onChange={(e) => setVerifierName(e.target.value)}
              sx={{ flex: 1, minWidth: 160 }}
            />
            <TextField
              size="small"
              label="Verifier email"
              value={verifierEmail}
              onChange={(e) => setVerifierEmail(e.target.value)}
              sx={{ flex: 1, minWidth: 160 }}
            />
            <Button variant="outlined" disabled={submitting} onClick={() => { void submitVerifierRequest(); }}>
              {submitting ? 'Saving…' : 'Record request'}
            </Button>
          </Stack>
        </CardContent>
      </Card>
    </Stack>
  );
};

export default ThirdPartyVerifierPanel;
